        assert afterFirst == U.UInt16ToSeq(|right| as U.uint16) + right + rest;
        assert input == U.UInt16ToSeq(|left| as U.uint16) + left +
                         U.UInt16ToSeq(|right| as U.uint16) + right + rest;
        Success(Pair(left, right, rest))
